    {"op": "rename", "mapping": {"email": "contact_email"}},
    {"op": "limit", "n": 100},
    {"op": "branch", "branches": [
      {"id": "premium", "when": "id > 100", "steps": [
        {"op": "select", "columns": ["id", "name"]}
      ]},
      {"when": "otherwise", "steps": [
        {"op": "select", "columns": ["id"]}
      ]}
    ]}
  ]},
  "dataset": [
    {"id": 150, "name": "Alice", "email": "alice@example.com"},
